import{_ as a,o as n,a as p,b as t}from"./app.UgfkfLuP.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"数据重排","link":"/api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/data_reorder"},{"text":"pack","link":"/api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/pack"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/pack.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/pack.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1793005388000}'),l={name:"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/pack.md"};function e(c,s,r,o,i,d){return n(),p("div",null,[...s[0]||(s[0]=[t(`<div><article class="markdown-body"><h1>pack</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tensor_api/experimental/arch/vector/reg_compute_sel.h&quot;</code>，命名空间为<code>asc::te::experimental</code>。</p><p>将源寄存器各元素的低半位宽数据按原顺序压缩，写入返回寄存器的低半部分或高半部分。<code>part</code>选择的是结果的存放位置，不是源元素中待提取的高位或低位。</p><ul><li>T为int16_t或uint16_t时，提取各元素的低8位，结果元素类型为uint8_t。</li><li>T为int32_t或uint32_t时，提取各元素的低16位，结果元素类型为uint16_t。</li><li>T为bool时，从掩码寄存器每两个比特中提取低位比特，即索引为0、2、4等偶数位置的比特，结果仍为掩码寄存器。</li></ul><p>有符号整型输入同样按位提取低半位宽，返回无符号整型寄存器，不保留源元素的符号。</p><p>本接口仅在AIV上生效。<code>part</code>为<code>high_low_part::low</code>时调用<a href="../../../c_api/reg_compute/reg_permute_sel/asc_pack_to_low.html">asc_pack_to_low</a>，为<code>high_low_part::high</code>时调用<a href="../../../c_api/reg_compute/reg_permute_sel/asc_pack_to_high.html">asc_pack_to_high</a>。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">high_low_part</span><span class="w"> </span><span class="n">part</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">high_low_part</span><span class="o">::</span><span class="n">low</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">decltype</span><span class="p">(</span><span class="k">auto</span><span class="p">)</span><span class="w"> </span><span class="n">pack</span><span class="p">(</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src</span><span class="p">);</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>part</td><td>压缩结果的存放位置。<code>high_low_part::low</code>表示结果寄存器的低半部分，<code>high_low_part::high</code>表示高半部分。默认值为<code>high_low_part::low</code>。</td></tr><tr><td>T</td><td>源寄存器的元素类型，支持的类型请参见<a href="#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">数据类型</a>。</td></tr></tbody></table><p><strong>表2</strong> 函数参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>src</td><td>输入</td><td>源操作数，类型为<a href="../reg_tensor/reg_tensor.html">reg_tensor&lt;T&gt;</a>。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><table><thead><tr><th>T</th><th>返回值类型</th></tr></thead><tbody><tr><td>bool</td><td>reg_tensor&lt;bool&gt;</td></tr><tr><td>int16_t</td><td>reg_tensor&lt;uint8_t&gt;</td></tr><tr><td>uint16_t</td><td>reg_tensor&lt;uint8_t&gt;</td></tr><tr><td>int32_t</td><td>reg_tensor&lt;uint16_t&gt;</td></tr><tr><td>uint32_t</td><td>reg_tensor&lt;uint16_t&gt;</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回类型由T推导，具体映射见数据类型表。<code>reg</code>的指定半部分保存压缩结果，<code>mask</code>直接复制<code>src.mask</code>。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>压缩计算不使用<code>src.mask</code>屏蔽元素，须保证参与压缩的源数据已初始化。</li><li>返回值直接继承<code>src.mask</code>，不会因元素位宽变化或结果存放位置而调整掩码。在后续操作使用掩码前，须根据结果元素位宽及有效位置重新绑定合适的掩码，参见<a href="../reg_tensor/reg_tensor.html#with_mask">with_mask</a>。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下代码片段在VF中调用。<code>src.reg</code>已初始化，先为源寄存器绑定全有效掩码，再提取低8位并写入结果低半部分。通过<a href="../mask_reg_compute/make_mask.html">make_mask</a>为结果构造uint8_t类型的低半部分掩码，避免使用另一半的数据。示例同时使用<a href="../mask_reg_compute/all_mask.html">all_mask</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">pack_example</span><span class="p">(</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="kt">uint16_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">src</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="kt">uint16_t</span><span class="o">&gt;</span><span class="p">());</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">result</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">pack</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">high_low_part</span><span class="o">::</span><span class="n">low</span><span class="o">&gt;</span><span class="p">(</span><span class="n">src</span><span class="p">);</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">low_mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">make_mask</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">mask_pattern</span><span class="o">::</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">result</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">low_mask</span><span class="p">);</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">result</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const g=a(l,[["render",e]]);export{h as __pageData,g as default};
